package com.nigson.commerce.cart;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.commerce.pricing.Pricing;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Commerce-owned context and line statements, with no reservation or provider call. */
public final class JdbcCartRepository implements CartRepository {
 private final JdbcTemplate jdbc;private final Clock clock;private final Pricing pricing;
 public JdbcCartRepository(JdbcTemplate jdbc,Clock clock,Pricing pricing){this.jdbc=jdbc;this.clock=clock;this.pricing=pricing;}
 public CartValues.Cart find(UUID party,UUID id,boolean lock){var rows=jdbc.query("SELECT id,market_id,organization_id,status,version,last_activity_at FROM commerce.cart WHERE id=? AND party_id=?"+(lock?" FOR UPDATE":""),(r,n)->new CartValues.Cart(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getString(4),List.of(),r.getLong(5),r.getTimestamp(6).toInstant()),id,party);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var c=rows.getFirst();var lines=jdbc.query("SELECT id,sku_id,quantity FROM commerce.cart_line WHERE cart_id=? ORDER BY sku_id LIMIT 101",(r,n)->new CartValues.Line(r.getObject(1,UUID.class),r.getObject(2,UUID.class),com.nigson.commerce.pricing.PricingValues.decimal(r.getBigDecimal(3))),id);if(lines.size()>100)throw CartValues.rule();return new CartValues.Cart(c.id(),c.marketId(),c.organizationId(),c.state(),List.copyOf(lines),c.version(),c.lastActivityAt());}
 public Created create(UUID party,CartValues.Create input,String actor){jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"cart-context:"+party+":"+input.marketId()+":"+Objects.toString(input.organizationId(),"RETAIL"));var markets=jdbc.query("SELECT m.id FROM commerce.market m JOIN commerce.currency c ON c.code=m.currency_code WHERE m.id=? AND m.code='NG' AND m.enabled AND c.active AND c.code='NGN' AND c.minor_unit=2 FOR SHARE OF m,c",(r,n)->r.getObject(1,UUID.class),input.marketId());if(markets.size()!=1)throw CartValues.rule();var active=jdbc.query("SELECT id FROM commerce.cart WHERE party_id=? AND market_id=? AND organization_id IS NOT DISTINCT FROM ?::uuid AND status='ACTIVE' FOR UPDATE",(r,n)->r.getObject(1,UUID.class),party,input.marketId(),input.organizationId());if(active.size()>1)throw CartValues.rule();if(active.size()==1)return new Created(find(party,active.getFirst(),false),false);UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO commerce.cart(id,created_by,updated_by,party_id,organization_id,market_id,status,last_activity_at) VALUES (?,?,?,?,?,?,'ACTIVE',?)",id,actor,actor,party,input.organizationId(),input.marketId(),java.sql.Timestamp.from(now()));return new Created(find(party,id,false),true);}
 private Instant now(){return clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS);}
 private void editable(CartValues.Cart c,long expected){if(c.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);if(!c.state().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);if(c.version()==Long.MAX_VALUE)throw CartValues.rule();}
 private void touch(UUID id,String actor){jdbc.update("UPDATE commerce.cart SET version=version+1,last_activity_at=?,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(now()),java.sql.Timestamp.from(now()),actor,id);}
 public CartValues.Cart set(UUID party,UUID id,UUID sku,long expected,CartValues.Quantity input,String actor){var c=find(party,id,true);editable(c,expected);boolean present=c.lines().stream().anyMatch(l->l.skuId().equals(sku));if(!present&&c.lines().size()>=100)throw CartValues.rule();Instant time=clock.instant();try{pricing.resolve(sku,new BigDecimal(input.quantity()),c.marketId(),c.organizationId(),time,time.plusSeconds(300),true);}catch(Problem.Failure invalid){if(invalid.getMessage().equals("PRICING_RULE_VIOLATION"))throw CartValues.rule();throw invalid;}jdbc.update("INSERT INTO commerce.cart_line(id,created_by,updated_by,cart_id,sku_id,quantity) VALUES (?,?,?,?,?,?) ON CONFLICT(cart_id,sku_id) DO UPDATE SET quantity=EXCLUDED.quantity,version=commerce.cart_line.version+1,updated_at=now(),updated_by=EXCLUDED.updated_by",EventCodec.uuid7(clock.instant()),actor,actor,id,sku,new BigDecimal(input.quantity()));touch(id,actor);return find(party,id,false);}
 public CartValues.Removed remove(UUID party,UUID id,UUID sku,long expected,String actor){var c=find(party,id,true);editable(c,expected);if(jdbc.update("DELETE FROM commerce.cart_line WHERE cart_id=? AND sku_id=?",id,sku)!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);touch(id,actor);return new CartValues.Removed(id,c.version()+1);}
}
